// ===== 等雨停 · 双页服务端校验版（Zeabur / 任意 Node 平台）=====
// 零依赖，只用 Node 内置模块，不需要 npm install
const http = require('http');

const PAYLOADS = {
  tzby: "zdNgGWgOBNDkurpT3hR4Fg==:8g/TLJ4VfuOkmiSw:",
  wszs: "srUeaYI5aMaFe4klmdllhw==:3P3ENM6AiMzc+N0S:"
};

const ITERATIONS = 200000;
const SITES = {"tzby":{"name":"等雨停虫二·天紫壁漾","password":"103035"},"wszs":{"name":"等雨停 · 尾数追杀","password":"221832"}};

const subtle = (globalThis.crypto && globalThis.crypto.subtle) ||
               require('crypto').webcrypto.subtle;

function b64ToBytes(b64) {
  const bin = atob(b64);
  const arr = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) arr[i] = bin.charCodeAt(i);
  return arr;
}

async function decryptContent(payload, pwd) {
  const p = payload.split(':');
  const km = await subtle.importKey(
    'raw', new TextEncoder().encode(pwd), 'PBKDF2', false, ['deriveKey']
  );
  const key = await subtle.deriveKey(
    { name: 'PBKDF2', salt: b64ToBytes(p[0]), iterations: ITERATIONS, hash: 'SHA-256' },
    km, { name: 'AES-GCM', length: 256 }, false, ['decrypt']
  );
  const plain = await subtle.decrypt({ name: 'AES-GCM', iv: b64ToBytes(p[1]) }, key, b64ToBytes(p[2]));
  return new TextDecoder().decode(plain);
}

const CORS = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
  'Access-Control-Allow-Headers': 'Content-Type'
};

function send(res, code, headers, body) {
  res.writeHead(code, Object.assign({ 'Content-Type': 'text/plain; charset=utf-8' }, headers));
  res.end(body);
}
function sendJson(res, code, obj) {
  send(res, code, { 'Content-Type': 'application/json; charset=utf-8' }, JSON.stringify(obj));
}

// 爆破计数：同 IP 错 10 次锁定（内存级，够用）
const fails = new Map();
setInterval(() => fails.clear(), 3600 * 1000);

function readBody(req) {
  return new Promise(resolve => {
    let d = '';
    req.on('data', c => { d += c; if (d.length > 1e5) req.destroy(); });
    req.on('end', () => resolve(d));
    req.on('error', () => resolve(''));
  });
}

const server = http.createServer(async (req, res) => {
  const url = new URL(req.url, 'http://localhost');
  const path = url.pathname;
  const ip = (req.headers['x-forwarded-for'] || '').split(',')[0] || req.socket.remoteAddress || 'unknown';

  if (req.method === 'OPTIONS') { send(res, 204, CORS, ''); return; }

  // —— 首页：根据 ?site= 显示对应锁屏页 ——
  if (req.method === 'GET' && (path === '/' || path === '/index.html')) {
    const site = url.searchParams.get('site') || 'tzby';
    if (!SITES[site]) { send(res, 400, CORS, '未知的页面标识'); return; }
    send(res, 200, { 'Content-Type': 'text/html; charset=utf-8' }, LOCK_PAGES[site]);
    return;
  }

  // —— 校验接口 ——
  if (req.method === 'POST' && path === '/api') {
    if ((fails.get(ip) || 0) >= 10) { sendJson(res, 429, { ok: false, msg: '尝试过于频繁，请稍后再试' }); return; }

    let body;
    try { body = JSON.parse((await readBody(req)) || '{}'); }
    catch (e) { sendJson(res, 400, { ok: false, msg: '请求格式错误' }); return; }

    const site = String(body.site || '');
    const payload = PAYLOADS[site];
    if (!payload) { sendJson(res, 400, { ok: false, msg: '页面标识无效' }); return; }

    const pwd = String(body.password || '').replace(/[^0-9]/g, '');
    if (!pwd) { sendJson(res, 400, { ok: false, msg: '请输入密码' }); return; }

    try {
      const html = await decryptContent(payload, pwd);
      if (!html || html.indexOf('<!DOCTYPE html>') !== 0) throw new Error('校验失败');
      fails.delete(ip);
      send(res, 200, { 'Content-Type': 'text/html; charset=utf-8' }, html);
    } catch (e) {
      fails.set(ip, (fails.get(ip) || 0) + 1);
      sendJson(res, 401, { ok: false, msg: '密码错误' });
    }
    return;
  }

  send(res, 404, CORS, 'Not Found');
});

const PORT = process.env.PORT || 8080;
server.listen(PORT, () => console.log('服务已启动，端口 ' + PORT));
